# Review package: 6d130c2..HEAD

## Commits
980ec4f test: tighten error-prefix assertion and add joiner/abbreviation cases

## Files changed
 test/sentenceCount.test.js | 4 ++++
 test/topWords.test.js      | 6 +++++-
 test/wordCount.test.js     | 2 ++
 3 files changed, 11 insertions(+), 1 deletion(-)

## Diff
diff --git a/test/sentenceCount.test.js b/test/sentenceCount.test.js
index 262fa7c..89c428a 100644
--- a/test/sentenceCount.test.js
+++ b/test/sentenceCount.test.js
@@ -75,20 +75,24 @@ test('does not end a sentence at a listed abbreviation', () => {
     assert.equal(sentenceCount(`${abbr}. Smith left.`), 1, abbr);
   }
 });

 test('compares abbreviations without regard to case', () => {
   for (const text of ['MR. Smith left.', 'mr. Smith left.', 'E.G. Smith left.', 'I.e. Smith left.', 'VS. Smith left.']) {
     assert.equal(sentenceCount(text), 1, text);
   }
 });

+test('does not end a sentence at a bracketed abbreviation', () => {
+  assert.equal(sentenceCount('(Mr.) Smith left.'), 1);
+});
+
 test('ends a sentence at an ellipsis after an abbreviation', () => {
   assert.equal(sentenceCount('Mr... Smith left.'), 2);
 });

 test('ends a sentence at an interrobang after an abbreviation', () => {
   assert.equal(sentenceCount('Dr?! Smith left.'), 2);
 });

 test('ends a sentence at a period after a word that is not an abbreviation', () => {
   assert.equal(sentenceCount('Mister. Smith left.'), 2);
diff --git a/test/topWords.test.js b/test/topWords.test.js
index 957027d..b0b285d 100644
--- a/test/topWords.test.js
+++ b/test/topWords.test.js
@@ -147,21 +147,25 @@ test('throws a RangeError naming the function for an invalid n', () => {
   for (const bad of [-1, 1.5, NaN, '3', undefined, null, Infinity, {}]) {
     assert.throws(() => topWords('apple', bad), (err) => {
       assert.ok(err instanceof RangeError, String(bad));
       assert.ok(err.message.startsWith('topWords:'), String(bad));
       return true;
     });
   }
 });

 test('validates the text before n', () => {
-  assert.throws(() => topWords(5, -1), TypeError);
+  assert.throws(() => topWords(5, -1), (err) => {
+    assert.ok(err instanceof TypeError);
+    assert.ok(err.message.startsWith('topWords:'));
+    return true;
+  });
   assert.throws(() => topWords(undefined, NaN), TypeError);
 });

 test('returns fresh objects on every call', () => {
   const first = topWords('apple apple pear', 2);
   first[0].count = 99;
   first[0].word = 'mutated';
   first.pop();
   assert.deepEqual(topWords('apple apple pear', 2), [
     { word: 'apple', count: 2 },
diff --git a/test/wordCount.test.js b/test/wordCount.test.js
index 025ebe1..f1a6d33 100644
--- a/test/wordCount.test.js
+++ b/test/wordCount.test.js
@@ -80,20 +80,22 @@ test('keeps a hyphen between letters inside a word', () => {
 test('drops a stray trailing hyphen or apostrophe from a word', () => {
   assert.equal(wordCount('well-'), 1);
   assert.equal(wordCount("dogs'"), 1);
   assert.equal(wordCount('dogs’ bark'), 2);
   assert.equal(wordCount('-well'), 1);
 });

 test('does not let a doubled joiner join two runs', () => {
   assert.equal(wordCount('a--b'), 2);
   assert.equal(wordCount("a''b"), 2);
+  assert.equal(wordCount("a-'b"), 2);
+  assert.equal(wordCount("a'-b"), 2);
 });

 test('separates words at em dashes and en dashes', () => {
   assert.equal(wordCount('one—two'), 2);
   assert.equal(wordCount('one–two'), 2);
 });

 test('separates words at slashes', () => {
   assert.equal(wordCount('and/or'), 2);
   assert.equal(wordCount('a/b\\c'), 3);

